pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(address nonOwner, address receiver, uint256 amount) public {
        vm.assume(nonOwner != address(0xc) && nonOwner != address(this));
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(nonOwner);
        try c.sendTo(receiver, amount) {} catch {}
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore);
    }
}
